    CONSTRAINT where_people_duty_demand_needed_ck CHECK (((needed >= 1) AND (needed <= 99))),
    CONSTRAINT where_people_duty_demand_position_ck CHECK (((length(btrim("position")) >= 1) AND (length(btrim("position")) <= 100)))
);


