-- Name: COLUMN where_people_duty_demand.needed; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.where_people_duty_demand.needed IS 'Number of employees of that position needed in the shift (1-99).';


--
-- Name: COLUMN where_people_duty_demand.location; Type: COMMENT; Schema: public; Owner: -
