--
-- Name: where_people_duty_entries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.where_people_duty_entries (
    id bigint NOT NULL,
    employee_id bigint NOT NULL,
    shift_id bigint,
    day date NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    changed_at timestamp with time zone DEFAULT now() NOT NULL,
    kind text DEFAULT 'shift'::text NOT NULL,
    starts_at text,
    ends_at text,
    break_minutes smallint,
    note text,
    CONSTRAINT where_people_duty_free_ck CHECK (((kind = 'free'::text) = ((starts_at IS NOT NULL) AND (ends_at IS NOT NULL) AND (break_minutes IS NOT NULL)))),
    CONSTRAINT where_people_duty_free_time_ck CHECK ((((starts_at IS NULL) OR (starts_at ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'::text)) AND ((ends_at IS NULL) OR (ends_at ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'::text)) AND ((break_minutes IS NULL) OR ((break_minutes >= 0) AND (break_minutes <= 720))))),
    CONSTRAINT where_people_duty_kind_ck CHECK ((kind = ANY (ARRAY['shift'::text, 'sick'::text, 'vacation'::text, 'free'::text]))),
    CONSTRAINT where_people_duty_note_len_ck CHECK (((note IS NULL) OR (length(note) <= 200))),
    CONSTRAINT where_people_duty_shift_ck CHECK (((kind = 'shift'::text) = (shift_id IS NOT NULL)))
);


--
-- Name: TABLE where_people_duty_entries; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.where_people_duty_entries IS 'Duty plan: shift of one employee on one day (at most one per day).';


--
-- Name: COLUMN where_people_duty_entries.kind; Type: COMMENT; Schema: public; Owner: -
