--
-- Name: where_people_planning; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.where_people_planning (
    id smallint DEFAULT 1 NOT NULL,
    min_rest_hours smallint DEFAULT 11 NOT NULL,
    max_daily_hours smallint DEFAULT 10 NOT NULL,
    max_weekly_hours smallint DEFAULT 48 NOT NULL,
    break_after_hours smallint DEFAULT 6 NOT NULL,
    break_minutes smallint DEFAULT 30 NOT NULL,
    long_break_after_hours smallint DEFAULT 9 NOT NULL,
    long_break_minutes smallint DEFAULT 60 NOT NULL,
    max_consecutive_days smallint DEFAULT 6 NOT NULL,
    min_days_off_per_week smallint DEFAULT 1 NOT NULL,
    sunday_work_allowed boolean DEFAULT false NOT NULL,
    holiday_work_allowed boolean DEFAULT false NOT NULL,
    respect_absence boolean DEFAULT true NOT NULL,
    planning_horizon smallint DEFAULT 4 NOT NULL,
    changed_at timestamp with time zone DEFAULT now() NOT NULL,
    compensate_sunday boolean DEFAULT false NOT NULL,
    planning_horizon_unit text DEFAULT 'weeks'::text NOT NULL,
    vacation_day_hours numeric(4,2) DEFAULT 8.00 NOT NULL,
    sick_day_hours numeric(4,2) DEFAULT 8.00 NOT NULL,
    vacation_color text DEFAULT '#0369A1'::text NOT NULL,
    sick_color text DEFAULT '#B91C1C'::text NOT NULL,
    balance_from date,
    free_weekend_every_six_weeks boolean DEFAULT true NOT NULL,
    extended_sunday_rest boolean DEFAULT true NOT NULL,
    apprentice_needs_company boolean DEFAULT true NOT NULL,
    import_public_holidays boolean DEFAULT false NOT NULL,
    import_regional_holidays boolean DEFAULT false NOT NULL,
    import_school_holidays boolean DEFAULT false NOT NULL,
    holiday_state text,
    holiday_color text DEFAULT '#B45309'::text NOT NULL,
    show_holidays boolean DEFAULT true NOT NULL,
    show_school_holidays boolean DEFAULT true NOT NULL,
    school_holiday_color text DEFAULT '#2563EB'::text NOT NULL,
    shift_rotation_days smallint DEFAULT 14 NOT NULL,
    min_consecutive_days smallint DEFAULT 1 NOT NULL,
    CONSTRAINT where_people_planning_absence_hours_ck CHECK (((vacation_day_hours >= (0)::numeric) AND (vacation_day_hours <= (24)::numeric) AND (sick_day_hours >= (0)::numeric) AND (sick_day_hours <= (24)::numeric))),
    CONSTRAINT where_people_planning_break_ck CHECK ((((break_after_hours >= 1) AND (break_after_hours <= 24)) AND ((break_minutes >= 0) AND (break_minutes <= 240)) AND ((long_break_after_hours >= 1) AND (long_break_after_hours <= 24)) AND ((long_break_minutes >= 0) AND (long_break_minutes <= 240)))),
    CONSTRAINT where_people_planning_colors_ck CHECK (((vacation_color ~ '^#[0-9A-F]{6}$'::text) AND (sick_color ~ '^#[0-9A-F]{6}$'::text))),
    CONSTRAINT where_people_planning_consecutive_order_ck CHECK ((min_consecutive_days <= max_consecutive_days)),
    CONSTRAINT where_people_planning_daily_ck CHECK (((max_daily_hours >= 1) AND (max_daily_hours <= 24))),
    CONSTRAINT where_people_planning_holiday_color_ck CHECK ((holiday_color ~ '^#[0-9A-F]{6}$'::text)),
    CONSTRAINT where_people_planning_holiday_state_ck CHECK (((holiday_state IS NULL) OR (holiday_state = ANY (ARRAY['BW'::text, 'BY'::text, 'BE'::text, 'BB'::text, 'HB'::text, 'HH'::text, 'HE'::text, 'MV'::text, 'NI'::text, 'NW'::text, 'RP'::text, 'SL'::text, 'SN'::text, 'ST'::text, 'SH'::text, 'TH'::text])))),
    CONSTRAINT where_people_planning_horizon_unit_ck CHECK ((planning_horizon_unit = ANY (ARRAY['weeks'::text, 'months'::text]))),
    CONSTRAINT where_people_planning_min_consecutive_ck CHECK (((min_consecutive_days >= 1) AND (min_consecutive_days <= 31))),
    CONSTRAINT where_people_planning_rest_ck CHECK (((min_rest_hours >= 0) AND (min_rest_hours <= 24))),
    CONSTRAINT where_people_planning_school_holiday_color_ck CHECK ((school_holiday_color ~ '^#[0-9A-F]{6}$'::text)),
    CONSTRAINT where_people_planning_shift_rotation_ck CHECK (((shift_rotation_days >= 1) AND (shift_rotation_days <= 365))),
    CONSTRAINT where_people_planning_single_ck CHECK ((id = 1)),
    CONSTRAINT where_people_planning_streak_ck CHECK ((((max_consecutive_days >= 1) AND (max_consecutive_days <= 31)) AND ((min_days_off_per_week >= 0) AND (min_days_off_per_week <= 7)) AND ((planning_horizon >= 1) AND (planning_horizon <=
CASE
    WHEN (planning_horizon_unit = 'months'::text) THEN 12
    ELSE 52
END)))),
    CONSTRAINT where_people_planning_weekly_ck CHECK (((max_weekly_hours >= 1) AND (max_weekly_hours <= 168)))
);


--
-- Name: TABLE where_people_planning; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.where_people_planning IS 'Rules of the duty planning: rest period, working time, breaks, week and horizon.';


