    CONSTRAINT where_people_shifts_band_ck CHECK ((band = ANY (ARRAY['frueh'::text, 'spaet'::text, 'zwischen'::text, 'frei'::text]))),
    CONSTRAINT where_people_shifts_break_ck CHECK (((break_minutes >= 0) AND (break_minutes <= 720))),
    CONSTRAINT where_people_shifts_clock_ck CHECK (((starts_at ~ '^[0-2][0-9]:[0-5][0-9]$'::text) AND (ends_at ~ '^[0-2][0-9]:[0-5][0-9]$'::text))),
    CONSTRAINT where_people_shifts_differ_ck CHECK ((starts_at <> ends_at))
);


--
-- Name: TABLE where_people_shifts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.where_people_shifts IS 'Shifts of the duty planning: name, time window, break and minimum staffing.';


--
-- Name: COLUMN where_people_shifts.band; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.where_people_shifts.band IS 'Half of the day the shift belongs to: frueh, spaet, zwischen — or frei for a whole free day.';


--
