INSERT INTO public."Artikel_Beschreibung" VALUES (33, 33, 1, 'Gaffa-Tape 50 mm schwarz', 'Gewebeband 50 mm × 50 m, rückstandsfrei', '50 mm × 50 m, Naturkautschuk, mattschwarz', NULL, 0, true, NULL, NULL, 'Mattschwarzes Gewebeband zum Abkleben von Kabeln und Kanten. Rückstandsfrei ablösbar, auch auf Bühnenboden.', NULL, NULL, NULL, 'Gewebeband 50 mm × 50 m, rückstandsfrei', false);
INSERT INTO public."Artikel_Beschreibung" VALUES (34, 34, 1, 'Leuchtmittel HPL 750 W', 'HPL-Lampe 750 W, 230 V, 4-fach gewendelt', '750 W, 230 V, Sockel G9.5, 1150 h', NULL, 0, true, NULL, NULL, 'Ersatzleuchtmittel für Profilscheinwerfer. Nur mit Handschuhen einsetzen, Fingerabdrücke verkürzen die Lebensdauer.', NULL, NULL, NULL, 'HPL-Lampe 750 W, 230 V, 4-fach gewendelt', false);
INSERT INTO public."Artikel_Beschreibung" VALUES (35, 35, 1, 'Nebelmaschine 1500 W', 'Nebelmaschine mit DMX und Timer', '1500 W, Aufheizzeit 6 s, Ausstoß 120 m³/min, DMX 512, 9,5 kg', NULL, 0, true, NULL, NULL, 'Nebelmaschine für Bühnennebel, Ausstoß über DMX steuerbar, Aufheizzeit kurz. Nur mit freigegebenem Nebelfluid betreiben.', NULL, NULL, NULL, 'Nebelmaschine mit DMX und Timer', false);
INSERT INTO public."Artikel_Beschreibung" VALUES (36, 36, 1, 'Konfettimaschine CO2', 'Konfettikanone für CO2-Betrieb', 'Reichweite 12 m, CO2-Flasche 2 kg, 6 kg', NULL, 0, true, NULL, NULL, 'Effektgerät für Konfettischüsse, Betrieb mit CO2-Flaschen. Aufstellbereich und Sicherheitsabstände nach Herstellerangabe.', NULL, NULL, NULL, 'Konfettikanone für CO2-Betrieb', false);
INSERT INTO public."Artikel_Beschreibung" VALUES (37, 37, 1, 'Bühnenpyro-Effektkörper 1.4G, 12er-Pack', 'Effektkörper Klasse 1.4G, VE 12', 'UN 0336, Klasse 1.4G, NEM ca. 12 g je Stück, VE 12', NULL, 0, true, NULL, NULL, 'Pyrotechnische Effektkörper für Bühnenanwendungen. Erwerb und Verwendung nur mit Erlaubnis nach SprengG; Lagerung nur in zugelassenen Behältern.', NULL, NULL, NULL, 'Effektkörper Klasse 1.4G, VE 12', false);
INSERT INTO public."Artikel_Beschreibung" VALUES (38, 38, 1, 'PAR-Scheinwerfer 64 (Altbestand)', 'Klassischer PAR-64, ausgemustert', NULL, NULL, 0, true, NULL, NULL, 'Altbestand an PAR-64-Gehäusen, wird nicht mehr disponiert und ist nur zur Nachvollziehbarkeit von Altdaten geführt.', NULL, NULL, NULL, 'Klassischer PAR-64, ausgemustert', false);
INSERT INTO public."Artikel_Beschreibung" VALUES (39, 39, 1, 'Stufenlinsen-Scheinwerfer 1 kW (Altbestand)', 'Alter Stufenlinser, nicht mehr im Umlauf', NULL, NULL, 0, true, NULL, NULL, 'Ausgemustertes Gerät. Bleibt mit Historie im Stamm, damit alte Belege zuordenbar bleiben.', NULL, NULL, NULL, 'Alter Stufenlinser, nicht mehr im Umlauf', false);
INSERT INTO public."Artikel_Beschreibung" VALUES (40, 40, 1, 'Rigging-Planung (Dienstleistung)', 'Planungsleistung, kein physischer Bestand', NULL, NULL, 0, true, NULL, NULL, 'Statische Prüfung und Rigging-Plan durch eine befähigte Person. Wird als Dienstleistungsposition abgerechnet, kein Lagerbestand.', NULL, NULL, NULL, 'Planungsleistung, kein physischer Bestand', false);
INSERT INTO public."Artikel_Beschreibung" VALUES (28, 28, 1, 'LED-Wall Panel 500×500 mm', 'LED-Panel 2,9 mm Pitch, 500 × 500 mm', 'Pitch 2,9 mm, 168×168 px, 180 W, 8 kg', NULL, 0, true, NULL, NULL, 'Feinpixel-LED-Panel für Bühnenbild und Präsentation. Verriegelungssystem, Netzteil- und Datenredundanz.', NULL, NULL, NULL, 'LED-Panel 2,9 mm Pitch, 500 × 500 mm', false);
INSERT INTO public."Artikel_Beschreibung" VALUES (29, 29, 1, 'Videoswitcher 8 Eingänge', 'Mischer mit 8 SDI-Eingängen, ISO-Aufzeichnung', '8× 12G-SDI, 2× HDMI, Multiview, 3,5 kg', NULL, 0, true, NULL, NULL, 'Live-Videomischer für Konferenzen und Streaming. 8 SDI-Eingänge, Multiview, USB-Disk-Aufzeichnung, Streaming-Engine.', NULL, NULL, NULL, 'Mischer mit 8 SDI-Eingängen, ISO-Aufzeichnung', false);


